//! Declared divergences from the frozen reference.
//!
//! The reference implementation is frozen as the FY 2025-26 parity oracle, and this crate is the
//! source of truth: a fix may change a test's output, but only as a declared divergence. A
//! divergence names its issue and test, says why, names who worked the right answer by hand, and
//! holds that answer as a patch over the oracle's golden for each input where it shows
//! (`expect`), and the dump keys a real-book parity run may see differ (`real_book_keys`). The
//! goldens themselves are never regenerated by this crate: a test compares Rust's dump with the
//! golden with its patches applied, so a change on any other input, or a patch that does not
//! show, fails the ordinary comparison ([`crate::compare::compare`]).
//!
//! A key is `figures[<id>]` or `findings[<id>]` (a whole entry: `null` removes it, an object adds
//! it where the golden has none), the same with `.<field>` for one field of an entry that exists,
//! or one of [`TOP_KEYS`]. The version fields and the test id cannot be patched: a divergence is
//! not a new test version. Wording is patched by its text (`title_text`, `limits_text`, ...), and
//! the hash the comparison reads is derived from it: a hash key itself cannot be patched, so the
//! person who signs the answer reads the words, and a wording patch cannot pass unseen. Two records
//! may not claim the same key, nor one an entry and the other a field of it.
//!
//! `ca_answer` says who worked the answer, by role, and the date it was signed (or the working
//! itself), never a person's or a client's name and never a pointer into material this repository
//! cannot show. A committed record's real-book keys are among the keys its patch sets
//! ([`parse_committed`]): what a real book may show differ is what was worked by hand. A real-book
//! key that names a per-book id (a ledger or party tag) belongs in a local, uncommitted registry
//! passed to `local_parity`, which [`parse`] reads.
//!
//! Not built yet: a fix that makes a test refuse an input it used to run on (an outcome patch).
//! Such a fix needs that first; until then it fails the comparison loudly.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt;

use serde::de::{self, Deserialize, Deserializer, MapAccess, SeqAccess, Visitor};
use serde_json::Value as Json;

use crate::canonical::{hash_ordered, nfc, sha16};

/// Each wording field and the hash the comparison reads for it.
const TEXT_HASH: [(&str, &str); 5] = [
    ("population_note_text", "population_note_sha256_16"),
    ("definition_text", "definition_sha256_16"),
    ("title_text", "title_sha256_16"),
    ("limits_text", "limits_sha256_16"),
    ("ask_client_text", "ask_client_sha256_16"),
];

/// A wording value as the canonical dump writes it: NFC-normalised, one text or a list.
fn nfc_wording(value: &Json) -> Json {
    match value {
        Json::String(text) => Json::String(nfc(text)),
        Json::Array(items) => Json::Array(items.iter().map(nfc_wording).collect()),
        other => other.clone(),
    }
}

/// The hash of a patched wording value: one text, or an ordered list of texts.
fn wording_hash(value: &Json) -> Result<String, String> {
    match value {
        Json::String(text) => Ok(sha16(text)),
        Json::Array(items) => items
            .iter()
            .map(|item| item.as_str().map(str::to_string))
            .collect::<Option<Vec<String>>>()
            .map(|items| hash_ordered(&items))
            .ok_or_else(|| "a wording list holds a value that is not text".to_string()),
        _ => Err("a wording value is not text".to_string()),
    }
}

/// The top-level dump keys a patch may set.
pub const TOP_KEYS: [&str; 7] = [
    "population_note_text",
    "book_invariants_evaluated",
    "book_invariant_violations",
    "result_invariants_evaluated",
    "result_invariant_violations",
    "module_invariants_evaluated",
    "module_invariant_violations",
];

/// One declared divergence. Only [`parse`] builds one (it cannot be written outside this crate),
/// so what `parse` checks holds for every divergence.
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub struct Divergence {
    pub id: String,
    pub issue: u64,
    pub test: String,
    pub why: String,
    pub ca_answer: String,
    /// Golden stem (e.g. `edge.<book>.<test>`) to the keys it patches and their values.
    pub expect: BTreeMap<String, BTreeMap<String, Json>>,
    pub real_book_keys: Vec<String>,
}

/// A JSON document in which no object repeats a key. `serde_json` keeps the last value of a
/// repeated key, so a record could show one value and enforce another; this refuses it instead.
struct NoRepeatedKeys;

impl<'de> Deserialize<'de> for NoRepeatedKeys {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        deserializer.deserialize_any(NoRepeatedKeys)
    }
}

impl<'de> Visitor<'de> for NoRepeatedKeys {
    type Value = Self;

    fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.write_str("a JSON value")
    }
    fn visit_bool<E>(self, _: bool) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_i64<E>(self, _: i64) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_u64<E>(self, _: u64) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_f64<E>(self, _: f64) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_str<E>(self, _: &str) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_unit<E>(self) -> Result<Self, E> {
        Ok(self)
    }
    fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> Result<Self, A::Error> {
        while seq.next_element::<Self>()?.is_some() {}
        Ok(self)
    }
    fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Self, A::Error> {
        let mut seen = BTreeSet::new();
        while let Some(key) = map.next_key::<String>()? {
            if !seen.insert(key.clone()) {
                return Err(de::Error::custom(format!("the key {key:?} appears twice")));
            }
            map.next_value::<Self>()?;
        }
        Ok(self)
    }
}

/// Parse the committed registry: a JSON list of records, each with exactly the fields of
/// [`Divergence`]. Refuses an unknown field, an empty `id`/`test`/`why`/`ca_answer`, issue 0, a
/// repeated id, a record that patches nothing and declares no real-book key, and a key that is not
/// in the grammar above, and a document in which an object repeats a key.
pub fn parse(text: &str) -> Result<Vec<Divergence>, String> {
    const FIELDS: [&str; 7] = [
        "id",
        "issue",
        "test",
        "why",
        "ca_answer",
        "expect",
        "real_book_keys",
    ];
    serde_json::from_str::<NoRepeatedKeys>(text).map_err(|e| format!("divergences: {e}"))?;
    let doc: Json = serde_json::from_str(text).map_err(|e| format!("divergences: {e}"))?;
    let records = doc
        .as_array()
        .ok_or("divergences: the registry is not a list")?;
    let mut seen = BTreeSet::new();
    let mut real_keys = BTreeSet::new();
    let mut out = Vec::new();
    for record in records {
        let fields = record
            .as_object()
            .ok_or("divergences: a record is not an object")?;
        if let Some(unknown) = fields.keys().find(|k| !FIELDS.contains(&k.as_str())) {
            return Err(format!("divergences: unknown field {unknown:?}"));
        }
        let text_of = |key: &str| -> Result<String, String> {
            record[key]
                .as_str()
                .filter(|v| !v.trim().is_empty())
                .map(str::to_string)
                .ok_or_else(|| format!("divergences: {key} is missing or empty"))
        };
        let id = text_of("id")?;
        if !seen.insert(id.clone()) {
            return Err(format!("divergences: {id} appears twice"));
        }
        let issue = record["issue"]
            .as_u64()
            .filter(|n| *n > 0)
            .ok_or_else(|| format!("divergences: {id}: issue is not an issue number"))?;
        let mut expect = BTreeMap::new();
        if let Some(stems) = record.get("expect") {
            let stems = stems
                .as_object()
                .ok_or_else(|| format!("divergences: {id}: expect is not an object"))?;
            for (stem, patch) in stems {
                let patch = patch
                    .as_object()
                    .filter(|p| !p.is_empty())
                    .ok_or_else(|| format!("divergences: {id}: {stem} patches nothing"))?;
                for key in patch.keys() {
                    Key::parse(key).map_err(|e| format!("divergences: {id}: {e}"))?;
                }
                expect.insert(stem.clone(), patch.clone().into_iter().collect());
            }
        }
        let real_book_keys = match record.get("real_book_keys") {
            None => Vec::new(),
            Some(keys) => keys
                .as_array()
                .ok_or_else(|| format!("divergences: {id}: real_book_keys is not a list"))?
                .iter()
                .map(|k| {
                    let k = k
                        .as_str()
                        .ok_or_else(|| format!("divergences: {id}: a real-book key is not text"))?;
                    let parsed = Key::parse(k).map_err(|e| format!("divergences: {id}: {e}"))?;
                    if matches!(&parsed, Key::Top(top) if top != "population_note_text") {
                        return Err(format!(
                            "divergences: {id}: real-book key {k} is a whole list"
                        ));
                    }
                    if !real_keys.insert((text_of("test")?, k.to_string())) {
                        return Err(format!(
                            "divergences: {id}: real-book key {k} is declared twice"
                        ));
                    }
                    Ok(k.to_string())
                })
                .collect::<Result<_, String>>()?,
        };
        if expect.is_empty() && real_book_keys.is_empty() {
            return Err(format!("divergences: {id} declares nothing"));
        }
        if expect.is_empty() {
            return Err(format!(
                "divergences: {id} declares real-book keys with no hand-worked patch"
            ));
        }
        out.push(Divergence {
            test: text_of("test")?,
            why: text_of("why")?,
            ca_answer: text_of("ca_answer")?,
            id,
            issue,
            expect,
            real_book_keys,
        });
    }
    Ok(out)
}

/// [`parse`] for the committed registry: also refuses a record whose real-book key is not one of
/// the keys its patch sets, so a real book is never let differ at a key no one worked by hand.
pub fn parse_committed(text: &str) -> Result<Vec<Divergence>, String> {
    let divergences = parse(text)?;
    for d in &divergences {
        if let Some(key) = d
            .real_book_keys
            .iter()
            .find(|key| !d.expect.values().any(|patch| patch.contains_key(*key)))
        {
            return Err(format!(
                "divergences: {}: real-book key {key} is not a key its patch sets",
                d.id
            ));
        }
    }
    Ok(divergences)
}

/// A parsed key.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Key {
    Entry {
        list: &'static str,
        id: String,
        field: Option<String>,
    },
    Top(String),
}

impl Key {
    /// The wording field this key names, if any.
    fn field_name(&self) -> Option<&str> {
        match self {
            Self::Top(key) => Some(key.as_str()),
            Self::Entry { field, .. } => field.as_deref(),
        }
    }

    /// The hash key the comparison reads for this key's wording, if it names wording.
    fn hash_key(&self) -> Option<Self> {
        let field = self.field_name()?;
        let (_, hash) = TEXT_HASH.iter().find(|(text, _)| *text == field)?;
        Some(match self {
            Self::Top(_) => Self::Top((*hash).to_string()),
            Self::Entry { list, id, .. } => Self::Entry {
                list,
                id: id.clone(),
                field: Some((*hash).to_string()),
            },
        })
    }

    /// The entry a key belongs to (`figures[<id>]`), for claims.
    fn entry(&self) -> Option<String> {
        match self {
            Self::Top(_) => None,
            Self::Entry { list, id, .. } => Some(format!("{list}[{id}]")),
        }
    }

    fn parse(key: &str) -> Result<Self, String> {
        for list in ["figures", "findings"] {
            if let Some(rest) = key.strip_prefix(list).and_then(|r| r.strip_prefix('[')) {
                let (id, after) = rest
                    .split_once(']')
                    .ok_or_else(|| format!("key {key:?} has no closing ]"))?;
                if id.is_empty() {
                    return Err(format!("key {key:?} names no id"));
                }
                let field = match after {
                    "" => None,
                    _ => Some(
                        after
                            .strip_prefix('.')
                            .filter(|f| !f.is_empty() && *f != "id")
                            .ok_or_else(|| format!("key {key:?} has no field after the id"))?
                            .to_string(),
                    ),
                };
                if field.as_deref().is_some_and(|f| f.ends_with("_sha256_16")) {
                    return Err(format!("key {key:?} is a hash: patch its text"));
                }
                return Ok(Self::Entry {
                    list,
                    id: id.to_string(),
                    field,
                });
            }
        }
        if TOP_KEYS.contains(&key) {
            Ok(Self::Top(key.to_string()))
        } else {
            Err(format!("key {key:?} cannot be patched"))
        }
    }

    /// The value at this key in `doc`, or `None` when the entry or field is absent.
    fn get<'a>(&self, doc: &'a Json) -> Option<&'a Json> {
        match self {
            Self::Top(key) => doc.get(key),
            Self::Entry { list, id, field } => {
                let entry = doc[*list]
                    .as_array()?
                    .iter()
                    .find(|e| e["id"].as_str() == Some(id))?;
                match field {
                    None => Some(entry),
                    Some(f) => entry.get(f),
                }
            }
        }
    }

    /// Set the value at this key (`null` on a whole entry removes it).
    fn set(&self, doc: &mut Json, value: Json) -> Result<(), String> {
        match self {
            Self::Top(key) => {
                doc[key] = value;
                Ok(())
            }
            Self::Entry { list, id, field } => {
                let entries = doc[*list]
                    .as_array_mut()
                    .ok_or_else(|| format!("the dump has no {list} list"))?;
                let at = entries.iter().position(|e| e["id"].as_str() == Some(id));
                match (field, at) {
                    (Some(f), Some(i)) if value.is_null() => {
                        if let Some(entry) = entries[i].as_object_mut() {
                            entry.remove(f.as_str());
                        }
                        Ok(())
                    }
                    (Some(f), Some(i)) => {
                        entries[i][f.as_str()] = value;
                        Ok(())
                    }
                    (Some(_), None) => Err(format!("{list}[{id}] is not in the dump")),
                    (None, Some(i)) if value.is_null() => {
                        entries.remove(i);
                        Ok(())
                    }
                    (None, None) if value["id"].as_str() == Some(id) => {
                        entries.push(value);
                        Ok(())
                    }
                    (None, _) => Err(format!(
                        "{list}[{id}]: a whole entry is removed with null where the golden has it, \
                         or added as an object with that id where it has none"
                    )),
                }
            }
        }
    }
}

/// The golden `stem` with every declared patch for it applied. Refuses a divergence whose `test`
/// is not the golden's `test_id`, a key the golden cannot take, and a patched value equal to the
/// oracle's (a declaration that changes nothing is stale or mistyped).
pub fn patched(oracle: &Json, stem: &str, divergences: &[Divergence]) -> Result<Json, String> {
    let mut doc = oracle.clone();
    let (mut keys, mut whole, mut fielded) = (BTreeSet::new(), BTreeSet::new(), BTreeSet::new());
    for d in divergences {
        let Some(patch) = d.expect.get(stem) else {
            continue;
        };
        if oracle["test_id"].as_str() != Some(d.test.as_str()) {
            return Err(format!("{}: {stem} is not a golden of {}", d.id, d.test));
        }
        for (key, value) in patch {
            let parsed = Key::parse(key).map_err(|e| format!("{}: {e}", d.id))?;
            let claimed = match (parsed.entry(), parsed.field_name()) {
                (Some(entry), None) => fielded.contains(&entry) || !whole.insert(entry),
                (Some(entry), Some(_)) => {
                    let clash = whole.contains(&entry);
                    fielded.insert(entry);
                    clash
                }
                (None, _) => false,
            };
            if claimed || !keys.insert(key.clone()) {
                return Err(format!("{}: {stem} {key} is claimed twice", d.id));
            }
            let mut value = if parsed.hash_key().is_some() {
                nfc_wording(value)
            } else {
                value.clone()
            };
            if parsed.get(oracle) == Some(&value)
                || (value.is_null() && parsed.get(oracle).is_none())
            {
                return Err(format!("{}: {stem} {key} equals the oracle", d.id));
            }
            if let Some(entry) = value.as_object_mut() {
                // A whole entry added: its wording hashes are derived from its texts too, and it
                // may not carry a hash of its own.
                if let Some(hash) = entry.keys().find(|k| k.ends_with("_sha256_16")) {
                    return Err(format!(
                        "{}: {stem} {key} carries {hash}: give its text",
                        d.id
                    ));
                }
                for (text, hash) in TEXT_HASH {
                    if let Some(words) = entry.get(text) {
                        let derived = wording_hash(words)
                            .map_err(|e| format!("{}: {stem} {key}: {e}", d.id))?;
                        entry.insert(hash.to_string(), Json::String(derived));
                    }
                }
            }
            parsed
                .set(&mut doc, value.clone())
                .map_err(|e| format!("{}: {stem} {e}", d.id))?;
            if let Some(hash) = parsed.hash_key() {
                let derived =
                    wording_hash(&value).map_err(|e| format!("{}: {stem} {key}: {e}", d.id))?;
                hash.set(&mut doc, Json::String(derived))
                    .map_err(|e| format!("{}: {stem} {e}", d.id))?;
            }
        }
    }
    Ok(doc)
}

/// For a real-book parity run of `test_id`: Rust's dump with the declared real-book keys of the
/// divergences named in `only` (the run's `--expect`) set back to the oracle's value, and the keys
/// that differed. A divergence not named stays strict: a difference at its keys is a difference. The caller then requires
/// [`crate::compare::compare`] to find nothing. A whole entry is masked only where one side lacks
/// it (an entry both sides hold is masked field by field, so a change to its other fields still
/// shows), and a list-valued top-level key is refused for the same reason. A masked wording field
/// takes the oracle's hash with it.
pub fn masked(
    rust: &Json,
    oracle: &Json,
    test_id: &str,
    divergences: &[Divergence],
    only: &[String],
) -> Result<(Json, Vec<String>), String> {
    let mut doc = rust.clone();
    let mut differed = Vec::new();
    for d in divergences
        .iter()
        .filter(|d| d.test == test_id && only.contains(&d.id))
    {
        for key in &d.real_book_keys {
            let parsed = Key::parse(key).map_err(|e| format!("{}: {e}", d.id))?;
            let (want, got) = (parsed.get(oracle), parsed.get(rust));
            // A whole top-level list cannot be masked: `parse` refuses it as a real-book key.
            if matches!(&parsed, Key::Entry { field: None, .. }) && want.is_some() && got.is_some()
            {
                return Err(format!(
                    "{}: {key} is on both sides: declare the fields that differ",
                    d.id
                ));
            }
            if want == got {
                continue;
            }
            differed.push(format!("{}: {key}", d.id));
            parsed
                .set(&mut doc, want.cloned().unwrap_or(Json::Null))
                .map_err(|e| format!("{}: {e}", d.id))?;
            if let Some(hash) = parsed.hash_key() {
                let oracle_hash = hash.get(oracle).cloned().unwrap_or(Json::Null);
                hash.set(&mut doc, oracle_hash)
                    .map_err(|e| format!("{}: {e}", d.id))?;
            }
        }
    }
    Ok((doc, differed))
}

/// The divergences named on a real-book run that did not show on it (`declared` as [`masked`]
/// returned it). An id that is not in the registry, or names another test, is refused.
pub fn expected_missing(
    expected: &[String],
    declared: &[String],
    test_id: &str,
    divergences: &[Divergence],
) -> Result<Vec<String>, String> {
    let mut missing = Vec::new();
    for id in expected {
        let d = divergences
            .iter()
            .find(|d| &d.id == id)
            .ok_or_else(|| format!("--expect {id}: no such divergence"))?;
        if d.test != test_id {
            return Err(format!("--expect {id}: it is a divergence of {}", d.test));
        }
        if !declared
            .iter()
            .any(|line| line.starts_with(&format!("{id}: ")))
        {
            missing.push(id.clone());
        }
    }
    Ok(missing)
}

/// `--divergences FILE` and `--expect ID` go together on a real-book run: a run that names a
/// registry says which of its divergences the read must show, and one that names divergences
/// names the registry they are in.
pub fn flags_pair(registry: Option<&str>, expected: &[String]) -> Result<(), String> {
    if expected.is_empty() == registry.is_none() {
        Ok(())
    } else {
        Err(
            "--divergences and --expect go together: name the divergences this read must show"
                .to_string(),
        )
    }
}

/// What a real-book parity run of one test found.
#[derive(Debug, Clone, PartialEq)]
pub struct RealBookRun {
    /// Each declared key that differed, with the oracle's value and Rust's.
    pub declared: Vec<String>,
    /// The divergences the run named that did not show on it.
    pub missing: Vec<String>,
    /// What [`crate::compare::compare`] found once the declared keys were masked.
    pub differences: Vec<String>,
}

impl RealBookRun {
    /// Nothing differed but the declared keys, and every divergence the run named showed.
    pub fn passed(&self) -> bool {
        self.differences.is_empty() && self.missing.is_empty()
    }
}

/// A real-book parity run: Rust's dump masked at the keys of the divergences named in `expected`
/// ([`masked`]), the named ones that did not show ([`expected_missing`]), and the comparison of
/// what is left with the oracle's dump.
pub fn real_book_run(
    rust: &Json,
    oracle: &Json,
    test_id: &str,
    divergences: &[Divergence],
    expected: &[String],
) -> Result<RealBookRun, String> {
    let refused = |e: String| format!("DIVERGENCES REFUSED: {e}");
    let (compared, declared) =
        masked(rust, oracle, test_id, divergences, expected).map_err(refused)?;
    let missing = expected_missing(expected, &declared, test_id, divergences).map_err(refused)?;
    let differences = crate::compare::compare(oracle, &compared, None)
        .map_err(|e| format!("PARITY REFUSED: {e}"))?;
    let shown = |doc: &Json, key: &Key| key.get(doc).map_or("absent".to_string(), Json::to_string);
    let declared = declared
        .into_iter()
        .map(|line| {
            let key = line
                .split_once(": ")
                .and_then(|(_, key)| Key::parse(key).ok());
            match key {
                Some(key) => format!(
                    "{line} (oracle {}, rust {})",
                    shown(oracle, &key),
                    shown(rust, &key)
                ),
                None => line,
            }
        })
        .collect();
    Ok(RealBookRun {
        declared,
        missing,
        differences,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn dump() -> Json {
        json!({
            "test_id": "t",
            "test_version": "1",
            "figures": [
                {"id": "t.a", "value": 1, "unit": "paise"},
                {"id": "t.b", "value": 2, "unit": "paise"}
            ],
            "findings": [{"id": "t/x", "confidence": "computed"}],
            "book_invariant_violations": []
        })
    }

    fn one(expect: Json, real: Json) -> Vec<Divergence> {
        parse(
            &json!([{
                "id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                "expect": expect, "real_book_keys": real
            }])
            .to_string(),
        )
        .unwrap()
    }

    #[test]
    fn a_patch_sets_removes_and_adds_entries_and_nothing_else() {
        let d = one(
            json!({"g": {
                "figures[t.a].value": 5,
                "figures[t.b]": null,
                "figures[t.c]": {"id": "t.c", "value": 3, "unit": "count"},
                "findings[t/x].confidence": "indicative"
            }}),
            json!([]),
        );
        let p = patched(&dump(), "g", &d).unwrap();
        assert_eq!(
            p["figures"],
            json!([
                {"id": "t.a", "value": 5, "unit": "paise"},
                {"id": "t.c", "value": 3, "unit": "count"}
            ])
        );
        assert_eq!(p["findings"][0]["confidence"], "indicative");
        // Another golden is untouched.
        assert_eq!(patched(&dump(), "other", &d).unwrap(), dump());
    }

    #[test]
    fn a_patch_that_changes_nothing_or_cannot_apply_is_refused() {
        for (patch, why) in [
            (json!({"figures[t.a].value": 1}), "equals the oracle"),
            (json!({"figures[t.z]": null}), "equals the oracle"),
            (json!({"figures[t.z].value": 1}), "is not in the dump"),
            (json!({"figures[t.a]": {"id": "t.a"}}), "a whole entry"),
            (json!({"figures[t.c]": {"id": "t.d"}}), "a whole entry"),
        ] {
            let d = one(json!({ "g": patch }), json!([]));
            let err = patched(&dump(), "g", &d).unwrap_err();
            assert!(err.contains(why), "{patch}: {err}");
        }
        let mut other = dump();
        other["test_id"] = json!("u");
        let d = one(json!({"g": {"figures[t.a].value": 5}}), json!([]));
        assert!(patched(&other, "g", &d)
            .unwrap_err()
            .contains("is not a golden of t"));
    }

    #[test]
    fn the_registry_refuses_what_it_cannot_honour() {
        let base = json!({"id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                          "expect": {"g": {"figures[t.a].value": 5}}});
        let cases = [
            (json!({"extra": 1}), "unknown field"),
            (json!({"issue": 0}), "issue"),
            (json!({"why": " "}), "why"),
            (json!({"ca_answer": null}), "ca_answer"),
            (
                json!({"expect": {"g": {"test_version": "2"}}}),
                "cannot be patched",
            ),
            (
                json!({"expect": {"g": {"figures[t.a].id": "x"}}}),
                "no field",
            ),
            (json!({"expect": {"g": {}}}), "patches nothing"),
            (json!({"expect": {}}), "declares nothing"),
            (
                json!({"real_book_keys": ["rules_version"]}),
                "cannot be patched",
            ),
            (
                json!({"real_book_keys": ["book_invariant_violations"]}),
                "whole list",
            ),
            (
                json!({"expect": {}, "real_book_keys": ["figures[t.a].value"]}),
                "no hand-worked patch",
            ),
        ];
        for (change, why) in cases {
            let mut record = base.clone();
            for (k, v) in change.as_object().unwrap() {
                record[k] = v.clone();
            }
            let err = parse(&json!([record]).to_string()).unwrap_err();
            assert!(err.contains(why), "{change}: {err}");
        }
        let twice = json!([base.clone(), base.clone()]).to_string();
        assert!(parse(&twice).unwrap_err().contains("appears twice"));
        let mut a = base.clone();
        a["real_book_keys"] = json!(["figures[t.a].value"]);
        let mut b = a.clone();
        b["id"] = json!("DV-2");
        assert!(parse(&json!([a, b]).to_string())
            .unwrap_err()
            .contains("declared twice"));
        assert_eq!(parse("[]").unwrap(), Vec::new());
    }

    #[test]
    fn a_real_book_run_masks_only_the_declared_keys_and_says_which_differed() {
        let d = one(
            json!({"g": {"figures[t.a].value": 5}}),
            json!(["figures[t.a].value", "figures[t.c]"]),
        );
        let mut rust = dump();
        rust["figures"][0]["value"] = json!(9);
        rust["figures"]
            .as_array_mut()
            .unwrap()
            .push(json!({"id": "t.c", "value": 3, "unit": "count"}));
        let (masked_rust, differed) =
            masked(&rust, &dump(), "t", &d, &["DV-1".to_string()]).unwrap();
        assert_eq!(masked_rust, dump());
        assert_eq!(differed, ["DV-1: figures[t.a].value", "DV-1: figures[t.c]"]);
        // Another test's divergence masks nothing.
        let (other, none) = masked(&rust, &dump(), "u", &d, &["DV-1".to_string()]).unwrap();
        assert_eq!(other, rust);
        assert!(none.is_empty());
    }

    #[test]
    fn masking_cannot_hide_more_than_the_declared_fields() {
        let d = one(
            json!({"g": {"figures[t.a].value": 5}}),
            json!(["figures[t.a]"]),
        );
        let err = masked(&dump(), &dump(), "t", &d, &["DV-1".to_string()]).unwrap_err();
        assert!(err.contains("on both sides"), "{err}");
        // Only the divergences a run names are masked; the others stay strict.
        let d = one(
            json!({"g": {"figures[t.a].value": 5}}),
            json!(["figures[t.a].value"]),
        );
        let mut rust = dump();
        rust["figures"][0]["value"] = json!(9);
        let (unmasked, none) = masked(&rust, &dump(), "t", &d, &[]).unwrap();
        assert_eq!(unmasked, rust);
        assert!(none.is_empty());
        // A field the oracle lacks is removed, not set to null.
        let d = one(
            json!({"g": {"figures[t.a].value": 5}}),
            json!(["figures[t.a].note"]),
        );
        let mut rust = dump();
        rust["figures"][0]["note"] = json!("x");
        assert_eq!(
            masked(&rust, &dump(), "t", &d, &["DV-1".to_string()])
                .unwrap()
                .0,
            dump()
        );
    }

    #[test]
    fn two_records_cannot_claim_one_key_or_an_entry_and_its_field() {
        let record = |id: &str, patch: Json| {
            json!({"id": id, "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                   "expect": {"g": patch}})
        };
        for (a, b) in [
            (
                json!({"figures[t.a].value": 5}),
                json!({"figures[t.a].value": 6}),
            ),
            (
                json!({"figures[t.a]": null}),
                json!({"figures[t.a].value": 6}),
            ),
            (
                json!({"figures[t.a].value": 5}),
                json!({"figures[t.a]": null}),
            ),
        ] {
            let d = parse(&json!([record("DV-1", a), record("DV-2", b)]).to_string()).unwrap();
            let err = patched(&dump(), "g", &d).unwrap_err();
            assert!(err.contains("claimed twice"), "{err}");
        }
    }

    #[test]
    fn wording_is_patched_by_its_text_and_its_hash_follows() {
        let mut oracle = dump();
        oracle["findings"][0]["title_text"] = json!("old");
        oracle["findings"][0]["title_sha256_16"] = json!(sha16("old"));
        oracle["findings"][0]["limits_text"] = json!(["a"]);
        oracle["findings"][0]["limits_sha256_16"] = json!(hash_ordered(&["a".to_string()]));
        let d = one(
            json!({"g": {
                "findings[t/x].title_text": "new",
                "findings[t/x].limits_text": ["a", "b"],
                "figures[t.c]": {"id": "t.c", "value": 3, "unit": "count", "definition_text": "d"}
            }}),
            json!([]),
        );
        let p = patched(&oracle, "g", &d).unwrap();
        assert_eq!(p["findings"][0]["title_sha256_16"], json!(sha16("new")));
        assert_eq!(
            p["findings"][0]["limits_sha256_16"],
            json!(hash_ordered(&["a".to_string(), "b".to_string()]))
        );
        assert_eq!(p["figures"][2]["definition_sha256_16"], json!(sha16("d")));
        // An added entry may not carry a hash of its own.
        let d = one(
            json!({"g": {"figures[t.c]": {"id": "t.c", "value": 3, "unit": "count",
                                          "definition_sha256_16": "0"}}}),
            json!([]),
        );
        assert!(patched(&oracle, "g", &d)
            .unwrap_err()
            .contains("carries definition_sha256_16"));
        // A hash cannot be patched by itself.
        let err = parse(
            &json!([{"id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                     "expect": {"g": {"findings[t/x].title_sha256_16": "0"}}}])
            .to_string(),
        )
        .unwrap_err();
        assert!(err.contains("is a hash"), "{err}");
    }

    #[test]
    fn an_expected_divergence_must_exist_belong_to_the_test_and_show() {
        let d = one(
            json!({"g": {"figures[t.a].value": 5}}),
            json!(["figures[t.a].value"]),
        );
        let shown = vec!["DV-1: figures[t.a].value".to_string()];
        assert!(expected_missing(&["DV-1".into()], &shown, "t", &d)
            .unwrap()
            .is_empty());
        assert_eq!(
            expected_missing(&["DV-1".into()], &[], "t", &d).unwrap(),
            ["DV-1"]
        );
        let other = vec!["DV-2: figures[t.a].value".to_string()];
        assert_eq!(
            expected_missing(&["DV-1".into()], &other, "t", &d).unwrap(),
            ["DV-1"]
        );
        assert!(expected_missing(&["DV-9".into()], &shown, "t", &d)
            .unwrap_err()
            .contains("no such divergence"));
        assert!(expected_missing(&["DV-1".into()], &shown, "u", &d)
            .unwrap_err()
            .contains("of t"));
    }
    #[test]
    fn a_key_repeated_in_any_object_is_refused() {
        let record = r#"{"id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                         "expect": {"g": {"figures[t.a].value": 5, "figures[t.a].value": 6}}}"#;
        let err = parse(&format!("[{record}]")).unwrap_err();
        assert!(
            err.contains(r#"the key "figures[t.a].value" appears twice"#),
            "{err}"
        );
        let top = r#"[{"id": "DV-1", "id": "DV-2", "issue": 1, "test": "t", "why": "w",
                       "ca_answer": "c", "expect": {"g": {"figures[t.a].value": 5}}}]"#;
        assert!(parse(top)
            .unwrap_err()
            .contains(r#"the key "id" appears twice"#));
        let fine = r#"[{"id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                        "expect": {"g": {"figures[t.a].value": 5}, "h": {"figures[t.a].value": 5}}}]"#;
        assert_eq!(parse(fine).unwrap().len(), 1);
    }

    #[test]
    fn a_committed_real_book_key_must_be_one_its_patch_sets() {
        let record = |real: Json| {
            json!([{"id": "DV-1", "issue": 1, "test": "t", "why": "w", "ca_answer": "c",
                    "expect": {"g": {"figures[t.a].value": 5}, "h": {"findings[t/x].confidence": "x"}},
                    "real_book_keys": real}])
            .to_string()
        };
        let other = record(json!(["figures[t.a].value", "figures[t.b].value"]));
        let err = parse_committed(&other).unwrap_err();
        assert!(
            err.contains("DV-1: real-book key figures[t.b].value is not a key its patch sets"),
            "{err}"
        );
        // A local registry may name per-book keys that no patch sets.
        assert_eq!(parse(&other).unwrap().len(), 1);
        let both = record(json!(["figures[t.a].value", "findings[t/x].confidence"]));
        assert_eq!(parse_committed(&both).unwrap(), parse(&both).unwrap());
    }

    #[test]
    fn the_registry_and_its_expectations_are_named_together() {
        let ids = ["DV-1".to_string()];
        assert_eq!(flags_pair(None, &[]), Ok(()));
        assert_eq!(flags_pair(Some("d.json"), &ids), Ok(()));
        for (registry, expected) in [(Some("d.json"), &[][..]), (None, &ids[..])] {
            assert!(flags_pair(registry, expected)
                .unwrap_err()
                .contains("go together"));
        }
    }

    #[test]
    fn a_real_book_run_passes_only_on_its_declared_keys_and_every_named_divergence() {
        let oracle: Json = serde_json::from_str(include_str!(
            "../tests/fixtures/golden/edge.ap_both.applicability_44ab.json"
        ))
        .unwrap();
        let key = "figures[applicability_44ab.gstr1_turnover].value";
        let d = parse(
            &json!([{"id": "DV-1", "issue": 1, "test": "applicability_44ab", "why": "w",
                     "ca_answer": "c", "expect": {"g": {key: 5}}, "real_book_keys": [key]}])
            .to_string(),
        )
        .unwrap();
        let named = ["DV-1".to_string()];
        let same = real_book_run(&oracle, &oracle, "applicability_44ab", &d, &[]).unwrap();
        assert!(same.passed() && same.declared.is_empty() && same.differences.is_empty());

        let mut rust = oracle.clone();
        Key::parse(key).unwrap().set(&mut rust, json!(7)).unwrap();
        let shown = real_book_run(&rust, &oracle, "applicability_44ab", &d, &named).unwrap();
        assert!(shown.passed(), "{shown:?}");
        assert_eq!(
            shown.declared,
            [format!("DV-1: {key} (oracle 10000000000, rust 7)")]
        );
        // Not named: the same change is a difference.
        let strict = real_book_run(&rust, &oracle, "applicability_44ab", &d, &[]).unwrap();
        assert!(!strict.passed() && !strict.differences.is_empty() && strict.missing.is_empty());
        // Named but not shown: missing.
        let absent = real_book_run(&oracle, &oracle, "applicability_44ab", &d, &named).unwrap();
        assert!(!absent.passed() && absent.differences.is_empty());
        assert_eq!(absent.missing, named);
        // A comparison that cannot run is refused, never passed.
        let mut empty = oracle.clone();
        empty["figures"] = json!([]);
        let err = real_book_run(&empty, &empty, "applicability_44ab", &d, &[]).unwrap_err();
        assert!(err.starts_with("PARITY REFUSED"), "{err}");
    }
}
